import{z as l,x as s,o as A,c as d,q as r,j as n,D as t,d as E,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"高频波动率与微观噪声","description":"","frontmatter":{"title":"高频波动率与微观噪声","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-hf-vol-noise.md","filePath":"quant/obd-hf-vol-noise.md","lastUpdated":1791063341000}'),p={name:"quant/obd-hf-vol-noise.md"};function u(h,a,F,c,m,f){const B=s("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="高频波动率与微观噪声" tabindex="-1">高频波动率与微观噪声 <a class="header-anchor" href="#高频波动率与微观噪声" aria-label="Permalink to &quot;高频波动率与微观噪声&quot;">​</a></h1><div class="epigraph"><p>采样越密，噪声越多：观测频率不是免费参数，由噪声与信号的相对预算决定，而不是「数据越多越好」。</p><footer>—— 据 Aït-Sahalia, Mykland and Zhang, Review of Financial Studies, 2005；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/obd-crossmarket-linkage">上一课</a>把跨市场的时钟钉住；本课回到单标的的读数问题：从 tick 读波动率。主干已写过<a href="/quant/microstructure-noise">微观结构噪声</a>、<a href="/quant/rv-noise">已实现波动与噪声</a>、<a href="/quant/pre-averaging">预平均</a>、<a href="/quant/tsrv">两尺度估计</a>与<a href="/quant/realized-kernel">已实现核</a>；本课深钻噪声与簿动力学的关系：噪声从哪来、它自己有什么结构、这个结构如何反过来约束估计量的设计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>密采样下已实现方差发散：噪声方差随采样频率线性进入估计，五秒收益的「波动率」可以主要不是波动。关键在于，这里的噪声不是仪器误差，而是前八课动力学的叠加投影：价差弹跳是点差动力学的影子（成交轮流打在两侧），取整是价格网格的影子，时间戳错序是撮合与时延的影子。把噪声当要消除的常数误差项，会错过它自己的结构——它有日内形状（开盘点差宽则噪声大），有跨票与跨市场的共同性，这些结构正是它「来自簿」的证据。</p><p><span class="marginnote">数字实例：取整噪声近似均匀分布，单次方差约 tick²/12。采样间隔从 5 分钟缩到 5 秒，样本数从 78 涨到 4680——涨 60 倍，灌进已实现方差的噪声也涨 60 倍，而真实信号方差一分不多。「越密越准」在这里方向恰好相反。</span></p><h3 id="噪声模型的层次" tabindex="-1">噪声模型的层次 <a class="header-anchor" href="#噪声模型的层次" aria-label="Permalink to &quot;噪声模型的层次&quot;">​</a></h3><p>MA(1) 是起步假设：噪声与自身滞后一阶相关，对应价差弹跳。更现实一层是依赖噪声：噪声与过去的有效收益相关，取整与时延都会造成。估计量跟着层次走：低噪声短记忆用已实现核，强噪声用预平均或两尺度；谱系与适用区间主干课已比较过，本课只钉选择依据——先诊断、后选型，不把一个估计量用到所有数据上。</p><p><span class="marginnote">术语翻译：MA(1) 噪声就是「只记得上一次」的误差——这笔成交弹到买侧，下一笔多半弹回卖侧，相邻两次误差负相关，隔一次就互不相干。它是价差弹跳最简单的数学画像，也是「短记忆」诊断的分界线。</span></p><p><span class="marginnote">signature plot 是最便宜的第一诊断：把已实现方差按采样频率画成曲线。若方差随频率单调上翘且不出现平台，说明噪声主导，任何「再密一点会更好」的直觉都该停下——平台的缺失本身就是噪声水平的信息。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程四步。诊断：signature plot 看噪声水平；先按第五课对齐会话——去季节与去噪次序不能反，对未除季节的序列估噪声，开盘的真波动会被记成噪声。选型：按噪声水平与记忆长度选估计量，频率内生——最优采样频率是噪声方差的函数，不是外生常数。噪声方差的估计与使用：估出来的噪声方差本身是输出，<a href="/quant/obd-flow-statespace">状态空间表示</a>的观测噪声与后面仿真校准课的价格网格参数都吃这个数。跨体制检查：噪声方差按点差与 tick 体制分箱报告，常数假设在此最常出错。</p>',12)),(A(),n(o,null,{default:t(()=>[i(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EFF%5B%22%E6%9C%89%E6%95%88%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20N1%5B%22%2B%20%E4%BB%B7%E5%B7%AE%E5%BC%B9%E8%B7%B3%22%5D%0A%20%20EFF%20--%3E%20N2%5B%22%2B%20tick%20%E5%8F%96%E6%95%B4%22%5D%0A%20%20EFF%20--%3E%20N3%5B%22%2B%20%E6%97%B6%E6%88%B3%E4%B8%8E%E6%8E%92%E5%BA%8F%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20N1%20--%3E%20OBS%5B%22%E8%A7%82%E6%B5%8B%20tick%20%E5%BA%8F%E5%88%97%22%5D%0A%20%20N2%20--%3E%20OBS%0A%20%20N3%20--%3E%20OBS%0A%20%20OBS%20--%3E%20SIG%5B%22signature%20plot%20%E8%AF%8A%E6%96%AD%22%5D%0A%20%20SIG%20--%3E%20CHOICE%5B%22%E4%BC%B0%E8%AE%A1%E9%87%8F%E9%80%89%E5%9E%8B%EF%BC%9A%E6%A0%B8%2F%E9%A2%84%E5%B9%B3%E5%9D%87%2F%E4%B8%A4%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20CHOICE%20--%3E%20OUT%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%96%B9%E5%B7%AE%20%2B%20%E5%99%AA%E5%A3%B0%E6%96%B9%E5%B7%AE%EF%BC%88%E9%9A%8F%E7%82%B9%E5%B7%AE%2Ftick%EF%BC%89%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("噪声-信号权衡在两个方差对频率的不同响应：信号方差不随采样加密增加，噪声方差随样本数线性累积——所以存在内生最优频率，"),e("a",{href:"/quant/microstructure-noise"},"Aït-Sahalia, Mykland and Zhang"),E(" 给出了它的位置。噪声与点差同源：成交落在买侧还是卖侧的随机性、报价更新的粒度，同时生成了点差与弹跳——有效点差估计与噪声方差是同一枚硬币的两面（Hasbrouck 的市场质量口径）。噪声的结构性还意味着它可以条件化：按点差体制分层估噪声，比全局常数更接近生成机制。")],-1)),a[5]||(a[5]=e("p",null,"两种方差对采样密度的响应方向相反，最优频率就是从这场拉锯里长出来的：",-1)),(A(),n(o,null,{default:t(()=>[i(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E9%87%87%E6%A0%B7%E9%97%B4%E9%9A%94%E5%8F%98%E5%AF%86%3A%E6%A0%B7%E6%9C%AC%E6%95%B0%20n%20%E5%8F%98%E5%A4%A7%22%5D%20--%3E%20S%5B%22%E4%BF%A1%E5%8F%B7%E6%96%B9%E5%B7%AE%3A%E4%B8%8D%E5%8F%98%22%5D%0A%20%20F%20--%3E%20N%5B%22%E5%99%AA%E5%A3%B0%E8%B4%A1%E7%8C%AE%3A%E9%9A%8F%20n%20%E7%BA%BF%E6%80%A7%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20S%20--%3E%20T%5B%22%E4%BC%B0%E8%AE%A1%E6%80%BB%E8%AF%AF%E5%B7%AE%20%3D%20%E4%BF%A1%E5%8F%B7%E8%AF%AF%E5%B7%AE%20%2B%20%E5%99%AA%E5%A3%B0%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20N%20--%3E%20T%0A%20%20T%20--%3E%20U%5B%22%E6%80%BB%E8%AF%AF%E5%B7%AE%E9%9A%8F%20n%20%E5%85%88%E9%99%8D%E5%90%8E%E5%8D%87%3AU%20%E5%BD%A2%22%5D%0A%20%20U%20--%3E%20Q%7B%22%E6%9C%80%E4%BC%98%E7%82%B9%E5%9C%A8%E5%93%AA%E4%BE%A7%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%99%AA%E5%A3%B0%E6%B0%B4%E5%B9%B3%E9%AB%98%22%7C%20L%5B%22%E5%81%8F%E7%A8%80%E7%96%8F%E4%B8%80%E4%BE%A7%3A%E5%A6%82%201-5%20%E5%88%86%E9%92%9F%22%5D%0A%20%20Q%20--%3E%7C%22%E5%99%AA%E5%A3%B0%E6%B0%B4%E5%B9%B3%E4%BD%8E%22%7C%20R%5B%22%E5%81%8F%E5%AF%86%E9%9B%86%E4%B8%80%E4%BE%A7%3A%E5%A6%82%E7%A7%92%E7%BA%A7%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>错法：跳过诊断直接定采样频率；噪声方差跨票跨体制搬运；先去噪后去季节把开盘当噪声；把两尺度修正当万能补丁——外推到噪声假设之外照样崩。</p><p><span class="marginnote">常见误区：初学者容易以为「数据精度高就该用满」。实际上越过最优点后继续加密，只是把取整与弹跳的方差往估计里灌；选频率先看 signature plot 有没有平台、在哪弯折，再看数据的名义精度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>噪声模型与真实撮合总有层差：依赖噪声之外还有突变成分（大跳价、开盘首笔），稳健估计量覆盖不了全部。噪声方差的估计精度有限：它靠自协方差的高阶项，短样本下抖动大。噪声与基本面波动的分离在极端时段失效：闪崩时段「噪声」与「价格发现」边界模糊，记成哪种结论完全不同。本课的噪声是读数层的，不处理样本选择与数据缺失——那是数据工程的边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>微观噪声是簿动力学的投影：价差弹跳、取整、时戳误差各有生成机制，不是白噪声误差项。</li><li>采样频率内生：噪声方差随频率线性累积，最优频率是噪声水平的函数。</li><li>流程：signature plot 诊断 → 去季节先行 → 估计量选型 → 噪声方差作为输出回填模型。</li><li>噪声与点差同源：按点差体制分层估噪声优于全局常数。</li><li>出处：Aït-Sahalia, Mykland and Zhang, <em>RFS</em>, 2005；Hasbrouck, <em>RFS</em>, 1993；估计量谱系见<a href="/quant/microstructure-noise">微观结构噪声</a>与<a href="/quant/tsrv">两尺度估计</a>。</li></ul>',6))])}const q=l(p,[["render",u]]);export{C as __pageData,q as default};
